def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.202.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.201.0"' not in init:
        sys.exit("ABORT: not at v3.201.0.")
    if "advanced_buying" not in data:
        sys.exit("ABORT: advanced_buying module not found in data file.")

    problems = _validate("PROC8", LESSONS_P8, QUESTIONS_P8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_P8))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — PROC8 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_P8)
    print(f"PROC 8 v3: {len(LESSONS_P8)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_P8):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["advanced_buying"]["lessons"] = LESSONS_P8
    data["advanced_buying"]["questions"] = bank
    data["advanced_buying"]["desc"] = ("Advanced buying and the procurement calendar in ZhiftERP: supplier scorecards on the 40/35/25 weights — price competitiveness, per-drop on-time-in-full delivery, and quality from the condition and claims records — computed from document variables with weight governance; the standings ladder with stated actions, gates, and documented overrides, and the measured-conversation rule; tiered relationship reviews from assembled agendas to outcome minutes with payment performance read both ways; buying-side blanket orders distinguished from rate arrangements, with call-offs, the consumption read, and expiry as negotiation; the subcontracting flow — service-rate orders, the subcontractor warehouse, assembled valuation, and the reconciliation cadence; Buying Settings as control-register rows; and the consolidated procurement calendar assembling every read from the track's eight modules.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.201.0"', '"3.202.0"'))
    print("  data: PROCUREMENT 8 lessons + bank REPLACED (style v3, textbook manual register) — TRACK COMPLETE")
    print("wrote __version__ -> 3.202.0")


if __name__ == "__main__":
    main()
